// =============================================================
// INTEGER.h — Fake R API: INTEGER
// Original R header: Rinternals.h
// Category: B — Accessor Macro or Inline Function
// Auto-generated by generate-r-extern-fake-header agent.
//
// INTEGER is declared in Rinternals.h as:
//   int *(INTEGER)(SEXP x);
// The parentheses around the name are a C idiom that prevents the
// declaration from being treated as a macro call even when a macro
// named INTEGER is in scope.
//
// The primary implementation of INTEGER is already provided by INTSXP.h
// (within the FAKE_ACCESSORS_DEFINED guard block), because INTSXP.h is the
// foundational header that defines SEXPREC, SEXP, allocVector, allocMatrix,
// and all four data accessors (INTEGER, REAL, LOGICAL, RAW) together.
// This header's role is therefore:
//   1. Pull in the full INTSXP.h + SEXP.h dependency chain so that any
//      translation unit that does `#include "INTEGER.h"` gets everything it
//      needs for INTEGER usage (all three patterns P1, P2, P3 from the guide).
//   2. Add INTEGER_RO — the const-qualified read-only companion declared at
//      Rinternals.h line 291 — which is absent from INTSXP.h.
//   3. Add INTEGER_OR_NULL — declared at Rinternals.h line 1153 — as a
//      conservative stub that simply calls INTEGER when the SEXP is non-NULL.
//   4. Re-export Rf_INTEGER (already defined in INTSXP.h) for completeness.
//   5. Emit the compatibility aliases block confirming that no separate
//      #define alias exists for INTEGER in the non-USE_RINTERNALS build path
//      (the real Rinternals.h uses the parenthesised function declaration
//      rather than a macro alias).
//
// Observed usage roles in rpart source (all 13 CSV rows):
//
//   P1: Assign int * from an input SEXP parameter
//       rpart.c:75    ncat  = INTEGER(ncat2);
//       rpart.c:76    xgrp  = INTEGER(xgrp2);
//       rpart.c:112   rp.numcat = INTEGER(ncat2);
//       xpred.c:69    ncat  = INTEGER(ncat2);
//       xpred.c:70    xgrp  = INTEGER(xgrp2);
//       xpred.c:110   rp.numcat = INTEGER(ncat2);
//
//   P2: Assign int * from a freshly allocated SEXP, or pass directly
//       rpart.c:195       rp.which = INTEGER(which3);
//       rpart.c:279       iptr = INTEGER(inode3);
//       rpart.c:286       iptr = INTEGER(isplit3);
//       rpart.c:295       iptr = INTEGER(csplit3);
//       pred_rpart.c:140  INTEGER(...) passed as function argument
//       rpartexp2.c:48    INTEGER(keep) passed as function argument
//
//   P3: Assign static int * from a SEXP obtained via R_getVar
//       rpart_callback.c:69  ndata = INTEGER(stemp);
//
// Integration Requirements (from INTEGER.md Section 5):
//   - INTSXP.h  : Defines SEXPREC/SEXP, SEXPTYPE block, allocVector,
//                 allocMatrix, INTEGER, REAL, LOGICAL, RAW, LENGTH,
//                 nrows/ncols, PROTECT/UNPROTECT, free_sexp, RError,
//                 sexptype_element_size.  Must precede this header.
//   - SEXP.h    : Adds asInteger/asReal/asLogical, TYPEOF, XLENGTH,
//                 R_NilValue, R_UnboundValue, R_NamesSymbol, CHAR/mkChar,
//                 VECTOR_ELT/SET_VECTOR_ELT, STRING_ELT/SET_STRING_ELT,
//                 setAttrib/getAttrib, isReal/isInteger/isNull, PRINTNAME,
//                 R_ProtectWithIndex, R_Reprotect, free_sexp_deep.
//                 Must follow INTSXP.h.
//   - fake_arena.h (not auto-generated; must be present in output_folder):
//                 ArenaFrame RAII guard.  INTEGER itself does not use the
//                 arena, but the enclosing rpart/xpred/pred_rpart/rpartexp2
//                 functions use ALLOC/R_alloc in the same bodies.
// =============================================================
#pragma once

#ifndef FAKE_INTEGER_H
#define FAKE_INTEGER_H

// --- Standard library includes ---
// (Most required includes are pulled in transitively by INTSXP.h and SEXP.h.)
#include <stddef.h>    // NULL, size_t

// --- Fake R header dependencies ---
// (from Integration Requirements in INTEGER.md Section 5)
//
// INTSXP.h provides the primary INTEGER inline definition under the guard
// FAKE_ACCESSORS_DEFINED, as well as SEXPREC, SEXP, SEXPTYPE constants,
// allocVector, allocMatrix, REAL, LOGICAL, RAW, LENGTH, nrows, ncols,
// PROTECT/UNPROTECT no-ops, free_sexp, RError, sexptype_element_size.
#include "INTSXP.h"

// SEXP.h provides asInteger, asReal, asLogical, TYPEOF, XLENGTH,
// R_NilValue, R_UnboundValue, R_NamesSymbol, CHAR, mkChar,
// VECTOR_ELT, SET_VECTOR_ELT, STRING_ELT, SET_STRING_ELT,
// setAttrib, getAttrib, isReal, isInteger, isNull, PRINTNAME,
// R_ProtectWithIndex, R_Reprotect, free_sexp_deep, R_NaString.
#include "SEXP.h"

// WARNING: dependency fake_arena.h not found in output_folder.
// ArenaFrame is required at the .Call-entry wrapper layer for any function
// that calls INTEGER and also uses ALLOC / R_alloc scratch allocations in
// the same body (rpart, xpred, pred_rpart, rpartexp2, init_rpcallback).
// INTEGER itself does not interact with the arena.  Once fake_arena.h is
// available, declare `ArenaFrame _frame;` as the first statement of every
// .Call-entry wrapper.
//
// #include "fake_arena.h"

// ---------------------------------------------------------------------------
// Core fake implementation — INTEGER accessor (Category B)
//
// NOTE: INTEGER is already defined in INTSXP.h under FAKE_ACCESSORS_DEFINED:
//
//   inline int *INTEGER(SEXP s) { return (int *) s->data; }
//
// The definition there is the authoritative one.  Nothing in this block
// redefines it; the FAKE_ACCESSORS_DEFINED guard prevents any duplicate
// definition.  The blocks below add companion items from Rinternals.h that
// were not included in INTSXP.h.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Pattern P1 — Assign to local or struct int * from an input SEXP parameter.
// (rpart.c:75-76, rpart.c:112, xpred.c:69-70, xpred.c:110)
//
// The original source lines compile unchanged through the INTEGER inline
// already in INTSXP.h:
//   ncat       = INTEGER(ncat2);   → ncat      = (int *) ncat2->data;
//   xgrp       = INTEGER(xgrp2);   → xgrp      = (int *) xgrp2->data;
//   rp.numcat  = INTEGER(ncat2);   → rp.numcat = (int *) ncat2->data;
//
// The SEXP arguments (ncat2, xgrp2) are .Call input parameters; Python
// must construct SEXPREC nodes with type=INTSXP and data pointing to a
// contiguous int[n] buffer before invoking the entry-point wrapper.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Pattern P2 — Assign to pointer from freshly allocated SEXP, or pass directly
// as a function argument.
// (rpart.c:195, rpart.c:279, rpart.c:286, rpart.c:295,
//  pred_rpart.c:140, rpartexp2.c:48)
//
// Also compiles unchanged; allocVector/allocMatrix from INTSXP.h create the
// SEXPs, and INTEGER extracts int * from their data buffers:
//   rp.which = INTEGER(which3);   → rp.which = (int *) which3->data;
//   iptr     = INTEGER(inode3);   → iptr     = (int *) inode3->data;
//   INTEGER(where)                → (int *) where->data  (passed as arg)
//
// Column-major striding (rpart.c:280-283, 287-290, 296-300) is valid because
// allocMatrix(INTSXP, nrow, ncol) allocates a flat int[nrow*ncol] buffer and
// the source advances iptr by nrow per column.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Pattern P3 — Assign static int * from SEXP obtained via R_getVar.
// (rpart_callback.c:69)
//
//   stemp = R_getVar(install("nback"), rho, FALSE);
//   ndata = INTEGER(stemp);   → ndata = (int *) stemp->data;
//
// Mechanically identical to P1.  stemp->data must hold a valid int[n] buffer
// when R_getVar is called through its Python-registered function-pointer bridge.
// This path is only reached during user-defined splitting (method=4); all
// standard rpart methods never invoke it.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// INTEGER_RO — read-only variant.
//
// Declared in Rinternals.h line 291 as:
//   const int *(INTEGER_RO)(SEXP x);
//
// Not used by the rpart source in the provided CSV subset, but present in the
// real header.  Provided here for any downstream include that may reference it.
// The fake simply adds const-qualification over the same cast as INTEGER.
// ---------------------------------------------------------------------------
#ifndef FAKE_INTEGER_RO_DEFINED
#define FAKE_INTEGER_RO_DEFINED

inline const int *INTEGER_RO(SEXP s) {
    return static_cast<const int *>(s->data);
}

#endif // FAKE_INTEGER_RO_DEFINED

// ---------------------------------------------------------------------------
// INTEGER_OR_NULL — returns int * if the SEXP is non-NULL (and non-NILSXP),
// otherwise returns NULL.
//
// Declared in Rinternals.h line 1153 as:
//   const int *(INTEGER_OR_NULL)(SEXP x);
//
// Not used by the rpart source.  Provided as a conservative stub for any
// downstream include that transitively requires it.
// ---------------------------------------------------------------------------
#ifndef FAKE_INTEGER_OR_NULL_DEFINED
#define FAKE_INTEGER_OR_NULL_DEFINED

inline const int *INTEGER_OR_NULL(SEXP s) {
    if (!s || s->type == NILSXP) return NULL;
    return static_cast<const int *>(s->data);
}

#endif // FAKE_INTEGER_OR_NULL_DEFINED

// ---------------------------------------------------------------------------
// --- Compatibility aliases (preserve original R API names) ---
//
// In the real Rinternals.h, the non-USE_RINTERNALS build path does NOT define
// a preprocessor #define alias for INTEGER.  The parenthesised declaration
//   int *(INTEGER)(SEXP x);
// is a C technique to declare a function named INTEGER even if a macro of the
// same name exists in scope — it resolves as a plain function call, not a
// macro expansion.  Therefore no #define alias is required or emitted here for
// INTEGER itself.
//
// The Rf_INTEGER alias (calling INTEGER) is already defined in INTSXP.h:
//   inline int *Rf_INTEGER(SEXP s) { return INTEGER(s); }
//
// INTEGER_RO and INTEGER_OR_NULL follow the same parenthesised declaration
// pattern in the real header and likewise need no preprocessor alias.
//
// Summary of aliases from the real Rinternals.h for INTEGER-family items:
//   INTEGER      — no #define alias (parenthesised function declaration)
//   INTEGER_RO   — no #define alias (parenthesised function declaration)
//   Rf_INTEGER   — provided as inline in INTSXP.h (not a #define in fake)
// ---------------------------------------------------------------------------

// --- ArenaFrame usage (informational; INTEGER is not Category C) ---
// INTEGER does not allocate arena memory.  The note below applies to the
// enclosing entry-point functions that call INTEGER alongside ALLOC/R_alloc.
//
// Declare `ArenaFrame _frame;` as the FIRST statement of any .Call-entry
// wrapper that calls rpart(), xpred(), pred_rpart(), rpartexp2(), or
// init_rpcallback(), since those functions use both INTEGER and arena-backed
// ALLOC/R_alloc scratch allocations in the same body.
//
// Example (.Call entry wrapper for rpart — illustrative):
//
//   #include "fake_arena.h"
//   extern "C" SEXP rpart_entry(
//           SEXP ncat2, SEXP method2, SEXP opt2,
//           SEXP parms2, SEXP xvals2, SEXP xgrp2,
//           SEXP ymat2, SEXP xmat2, SEXP wt2, SEXP ny2, SEXP cost2) {
//       ArenaFrame _frame;    // frees ALLOC/R_alloc scratch on exit
//       try {
//           return rpart(ncat2, method2, opt2, parms2, xvals2, xgrp2,
//                        ymat2, xmat2, wt2, ny2, cost2);
//       } catch (const RError &e) {
//           set_python_error(e.what());
//           return R_NilValue;
//       }
//   }
//
// SEXP return values (which3, inode3, isplit3, csplit3, etc.) are
// heap-allocated via malloc() inside allocVector/allocMatrix and survive
// ArenaFrame destruction.  Python extracts element arrays via INTEGER() and
// calls free_sexp() / free_sexp_deep() after copying.

#endif // FAKE_INTEGER_H
